import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
from pathlib import Path
import numpy as np

# --- Configuration ---
# Point to the files generated by the previous script
ORIGINAL_YIELD_FILE = Path("data/02_intermediate/sugarbeet_yield.csv")
TECH_YIELD_FILE = Path("data/02_intermediate/detrended_yield/Y_tech.csv")
WEATHER_YIELD_FILE = Path("data/02_intermediate/detrended_yield/Y_weather.csv")

# How many random districts to plot for visual inspection
NUM_DISTRICTS_TO_PLOT = 4


# --- Main Verification Function ---
def verify_output():
    """Loads and verifies the detrending output files."""

    print("--- Starting Verification Process ---")

    # Check if files exist
    if not all([ORIGINAL_YIELD_FILE.exists(), TECH_YIELD_FILE.exists(), WEATHER_YIELD_FILE.exists()]):
        print("Error: Not all required input files were found. Please run the main script first.")
        return

    # Load all datasets
    df_orig = pd.read_csv(ORIGINAL_YIELD_FILE)
    df_tech = pd.read_csv(TECH_YIELD_FILE)
    df_weather = pd.read_csv(WEATHER_YIELD_FILE)

    # Merge them into a single DataFrame for easy comparison
    df_merged = pd.merge(df_orig, df_tech, on=['district_no', 'year'])
    df_merged = pd.merge(df_merged, df_weather, on=['district_no', 'year'])

    print(f"Successfully loaded and merged data. Total records: {len(df_merged)}")

    # --- 1. Statistical Sanity Check ---
    print("\n--- 1. Statistical Sanity Check ---")

    # The mean of residuals (y_weather) should be very close to zero.
    mean_residual = df_merged['y_weather'].mean()
    print(f"Overall mean of y_weather (residuals): {mean_residual:.4f}")
    if np.isclose(mean_residual, 0):
        print("PASS: Overall mean of residuals is close to zero.")
    else:
        print("WARNING: Overall mean of residuals is not close to zero. There might be a systematic bias.")

    # Check the core equation: y_observed = y_tech + y_weather
    df_merged['check_sum'] = df_merged['y_tech'] + df_merged['y_weather']
    reconstruction_error = (df_merged['yield'] - df_merged['check_sum']).abs().mean()
    print(f"Mean absolute reconstruction error (yield - (y_tech + y_weather))): {reconstruction_error:.4f}")
    if np.isclose(reconstruction_error, 0):
        print("PASS: The relationship y_observed = y_tech + y_weather holds true.")
    else:
        print("FAIL: The output components do not sum back to the original observed yield.")

    # --- 2. Visual Spot-Check ---
    print(f"\n--- 2. Visual Spot-Check for {NUM_DISTRICTS_TO_PLOT} Random Districts ---")

    # Get a list of unique districts and pick some random ones
    all_districts = df_merged['district_no'].unique()
    districts_to_plot = np.random.choice(all_districts, size=NUM_DISTRICTS_TO_PLOT, replace=False)

    print(f"Randomly selected districts for plotting: {districts_to_plot}")

    # Create a subplot for each district
    fig, axes = plt.subplots(NUM_DISTRICTS_TO_PLOT, 1, figsize=(12, 4 * NUM_DISTRICTS_TO_PLOT), sharex=True)
    fig.suptitle('Verification of GAM Detrending for Sample Districts', fontsize=16)

    for i, district in enumerate(districts_to_plot):
        ax = axes[i]
        district_data = df_merged[df_merged['district_no'] == district].sort_values('year')

        # Plot 1: Observed Yield and Smoothed Trend
        ax.plot(district_data['year'], district_data['yield'], 'o-', label='Observed Yield', color='gray', alpha=0.7)
        ax.plot(district_data['year'], district_data['y_tech'], '-', label='Y_tech (GAM Trend)', color='cornflowerblue',
                linewidth=2.5)

        # Plot 2: Weather Residuals on a secondary axis or overlaid
        ax2 = ax.twinx()
        ax2.bar(district_data['year'], district_data['y_weather'], label='Y_weather (Residual)', color='orange',
                alpha=0.5)
        ax2.axhline(0, linestyle='--', color='red', linewidth=1)
        ax2.set_ylabel('Weather Component (Residual)', color='orange')
        ax2.tick_params(axis='y', labelcolor='orange')

        ax.set_title(f'District: {district}')
        ax.set_ylabel('Yield & Trend Component')
        ax.legend(loc='upper left')
        ax.grid(True, linestyle='--', alpha=0.6)

    plt.xlabel('Year')
    plt.tight_layout(rect=[0, 0.03, 1, 0.97])  # Adjust layout to make room for suptitle

    # Save the plot to the output directory
    plot_filename = Path(WEATHER_YIELD_FILE).parent / 'verification_plot.png'
    plt.savefig(plot_filename)
    print(f"\nVerification plot saved to: {plot_filename}")
    plt.show()


# --- Run the script ---
if __name__ == '__main__':
    verify_output()